import { NextRequest, NextResponse } from 'next/server';

const BACKEND_URL = process.env.NEXT_PUBLIC_API_BASE_URL || 'http://62.84.115.11:8000';

/**
 * Прокси для запросов к /api/auth/telegram-login/
 * Обходит CORS проблемы в dev режиме
 */
export async function GET(request: NextRequest) {
  try {
    // Получаем cookies из оригинального запроса
    const cookies = request.headers.get('cookie') || '';
    
    // Собираем все заголовки для передачи на бэкенд
    const headers: HeadersInit = {
      'Content-Type': 'application/json',
    };
    
    // Передаем cookies если они есть
    if (cookies) {
      headers['Cookie'] = cookies;
    }
    
    // Делаем запрос к бэкенду
    const response = await fetch(`${BACKEND_URL}/api/auth/telegram-login/`, {
      method: 'GET',
      headers,
      // На сервере нет CORS ограничений
    });

    // Проверяем, есть ли данные для парсинга
    let data;
    const contentType = response.headers.get('content-type');
    if (contentType && contentType.includes('application/json')) {
      data = await response.json();
    } else {
      const text = await response.text();
      data = text ? JSON.parse(text) : {};
    }
    
    // Копируем Set-Cookie заголовки от бэкенда, если они есть
    const responseHeaders: HeadersInit = {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization',
      'Access-Control-Allow-Credentials': 'true',
    };
    
    // Копируем Set-Cookie заголовки
    const setCookieHeader = response.headers.get('set-cookie');
    if (setCookieHeader) {
      responseHeaders['Set-Cookie'] = setCookieHeader;
    }
    
    // Возвращаем ответ с теми же заголовками, что и бэкенд
    return NextResponse.json(data, {
      status: response.status,
      headers: responseHeaders,
    });
  } catch (error) {
    console.error('Proxy error:', error);
    return NextResponse.json(
      { error: 'Failed to proxy request', details: error instanceof Error ? error.message : 'Unknown error' },
      { status: 500 }
    );
  }
}

// Обработка OPTIONS для preflight запросов
export async function OPTIONS() {
  return new NextResponse(null, {
    status: 200,
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization',
      'Access-Control-Allow-Credentials': 'true',
    },
  });
}
